WITH filtered AS (SELECT *, LEAST(quantity, unit_price) AS least_quantity_unit_price, ROUND(quantity, 0) AS quantity_rounded FROM order_items WHERE product_id IS NOT NULL AND order_id IN (8, 16, 37, 40)), remaining_keys AS (SELECT product_id, order_id FROM filtered EXCEPT SELECT product_id, order_id FROM order_items WHERE quantity > 4), kept_rows AS (SELECT s.* FROM filtered s INNER JOIN remaining_keys k ON s.product_id = k.product_id AND s.order_id = k.order_id), metrics AS (SELECT *, CUME_DIST() OVER (ORDER BY quantity DESC NULLS FIRST) AS quantity_cume_dist, DENSE_RANK() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC NULLS FIRST) AS quantity_dense_rank FROM kept_rows WHERE product_id IS NOT NULL), with_dims AS (SELECT src.*, d.status, d.amount FROM metrics src LEFT JOIN orders d ON src.order_id = d.id), joined AS (SELECT e.order_id, e.product_id, e.quantity, e.unit_price, e.least_quantity_unit_price, e.quantity_cume_dist, e.quantity_dense_rank, e.status, p.shipping_fee FROM with_dims e INNER JOIN orders p ON e.order_id = p.id) SELECT s.order_id, s.unit_price, s.quantity_cume_dist, s.status, s.shipping_fee, (SELECT MAX(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS max_payment_amount FROM joined s ORDER BY max_payment_amount DESC;
